/**
 * @name User-controlled dynamic attribute access
 * @description Taint tracking from JMESPath query input to getattr
 * @kind path-problem
 * @problem.severity warning
 * @id py/jmespath-getattr-taint
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module GetattrTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources: jmespath.search(expression, ...), jmespath.compile(expression)
    // We target the 'expression' argument which is the 0th arg.
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("jmespath").getMember("search").getACall() or
        call = API::moduleImport("jmespath").getMember("compile").getACall()
      ) and
      source = call.getArg(0)
    )
    or
    // Also consider the command line argument in bin/jp.py if possible, though that's a script.
    // Let's stick to library usage first.
    none()
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: the attribute name argument of getattr
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("getattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module GetattrTaintFlow = TaintTracking::Global<GetattrTaintConfig>;
import GetattrTaintFlow::PathGraph

from GetattrTaintFlow::PathNode source, GetattrTaintFlow::PathNode sink
where GetattrTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic attribute access controlled by user input from $@.", source.getNode(), "JMESPath expression"
